// Reshape the parallel arrays from the HTML Extract node into one tender object per row.
// Column order on eprocure.gov.in: td(1)=Title (with a leading 'N. ' number + anchor text),
// td(2)=Reference No (this is the real unique tender ID), td(3)=Closing Date, td(4)=Bid Opening Date.
const extracted = items[0]?.json || {};
const titles = extracted.tenderTitle || [];
const refs = extracted.referenceNo || [];
const closing = extracted.closingDate || [];
const opening = extracted.bidOpeningDate || [];

const tenders = [];
for (let i = 0; i < refs.length; i++) {
  const tenderId = (refs[i] || '').toString().trim();
  if (!tenderId) continue;
  // Strip the auto-numbered prefix the marquee widget adds, e.g. "3. Annual Afloat repair..." -> "Annual Afloat repair..."
  const rawTitle = (titles[i] || '').toString().trim();
  const title = rawTitle.replace(/^\d+\.\s*/, '');
  tenders.push({
    source: 'eprocure',
    tenderId,
    title,
    department: '',
    closingDate: (closing[i] || '').toString().trim(),
    bidOpeningDate: (opening[i] || '').toString().trim(),
    link: 'https://eprocure.gov.in/eprocure/app'
  });
}

return tenders.map(t => ({ json: t }));

// Drop anything whose tenderId already exists in Google Sheets.
let existingIds = new Set();
try {
  const existingRows = $('Google Sheets - Get Existing Tenders2').all();
  existingIds = new Set(
    existingRows.map(r => (r.json.tenderId || '').toString().trim()).filter(Boolean)
  );
} catch (e) {
  // Sheet fetch hasn't run or came back empty — treat everything as new
  existingIds = new Set();
}

const seen = new Set();
const newTenders = [];
for (const item of items) {
  const t = item.json;
  const id = (t.tenderId || '').toString().trim();
  if (!id || existingIds.has(id) || seen.has(id)) continue;
  seen.add(id);
  newTenders.push(t);
}

return newTenders.map(t => ({ json: t }));

// Sort by closing date (soonest first), then take the top 5.
function parseClosingDate(str) {
  // Handles format like "24-Aug-2026 03:00 PM"
  const parsed = Date.parse(str.replace(/(\d{2})-(\w{3})-(\d{4})/, '$2 $1, $3'));
  return isNaN(parsed) ? Infinity : parsed;
}

const sorted = [...items].sort((a, b) =>
  parseClosingDate(a.json.closingDate) - parseClosingDate(b.json.closingDate)
);

return sorted.slice(0, 5);
